using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using NihonUnisys.CoreCenter.Core;
using NihonUnisys.CoreCenter.Retail.Ordering.AutoOrder.Business;
using NihonUnisys.CoreCenter.Retail.SalesTalking.PublicBusiness.Business;
using NihonUnisys.CoreCenter.DistributionCommon.Common.MasterBusiness.DataTransferObject;
using NihonUnisys.CoreCenter.Retail.Ordering.ReceptOrder.Business;

namespace NihonUnisys.CoreCenter.Retail.Ordering.AutoOrder.Facade
{
    /// <summary>
    /// クラスID「BSFCORR0609」
    /// </summary>
    public class AutoOrderDataLoaderFacade : FacadeBase, IAutoOrderDataLoaderFacade
    {
        #region 自動発注データ取込準備処理 [FsメソッドID: BSFCORR060900001]
        /// <summary>
        ///  自動発注データ取込準備処理
        ///  [FsメソッドID: BSFCORR060900001]
        /// </summary>
        /// <param name="startParameterEntity">起動パラメータEntity</param>
        /// <param name="automaticOrderDataTakingConditionEntity">（OUT）自動発注データ取込条件Entity</param>
        /// <param name="cmcSystemDateDataSet">（OUT）CMC業務日付DataSet</param>
        /// <param name="orderDeliveryDateDecisionCommonInfoEntity">（OUT）発注日・納品日決定共通情報Entity</param>
        /// <param name="strDistributionPatternDisclosureDataSet">（OUT）ＳＴＲ物流パターン公開用DataSet</param>
        /// <param name="storeGroupDisclosureDataSet">（OUT）ＣＭＣ店舗グループ公開DataSet</param>
        /// <param name="strDeliveryPatternDisclosureDataSet">（OUT）ＳＴＲ便パターン公開用DataSet</param>
        /// <param name="workAutomaticOrderingDataSet">（OUT）ワーク自動発注情報DataSet</param>
        /// <param name="orderSystemDate">発注業務実施日時</param>
        /// <param name="apVariablesDataSet">（OUT)ＡＰ変数DataSet</param>
        [FacadeMethod("BSFCORR060900001")]
        public virtual void GetAutoOrderDataLoaderPrepares(
              StartParameterEntity startParameterEntity
            , ref AutomaticOrderDataTakingConditionEntity automaticOrderDataTakingConditionEntity
            , ref CMCSystemDateDataSet cmcSystemDateDataSet
            , ref OrderDeliveryDateDecisionCommonInfoEntity orderDeliveryDateDecisionCommonInfoEntity
            , ref STRDistributionPatternDisclosureDataSet strDistributionPatternDisclosureDataSet
            , ref StoreGroupDisclosureDataSet storeGroupDisclosureDataSet
            , ref STRDeliveryPatternDisclosureDataSet strDeliveryPatternDisclosureDataSet
            , ref WorkAutomaticOrderingDataSet workAutomaticOrderingDataSet
            , DateTime orderSystemDate
            , ref APVariablesDataSet apVariablesDataSet
            )
        {
            // [BSクラスID: BSCORR06009] DIインスタンス化
            AutoOrder.Business.IAutoOrderDataLoaderBusiness autoOrder =
                (AutoOrder.Business.IAutoOrderDataLoaderBusiness)ClassObjectUtil.GetBusinessInstance(
                    "BSCORR06009", typeof(AutoOrder.Business.IAutoOrderDataLoaderBusiness)
                );
            
            //１．【自動発注データ取込準備をする】（BSCORR06009000001）ビジネスを呼び出す。
            autoOrder.GetAutoOrderDataLoaderPrepares(
                  startParameterEntity
                , automaticOrderDataTakingConditionEntity
                , cmcSystemDateDataSet
                , orderDeliveryDateDecisionCommonInfoEntity
                , strDistributionPatternDisclosureDataSet
                , storeGroupDisclosureDataSet
                , strDeliveryPatternDisclosureDataSet
                , apVariablesDataSet
                );

            //２．【自動発注トラン取得】（BSCORR06009000002）ビジネスを呼び出す。
            autoOrder.GetAutomaticOrderingTransaction(
                  startParameterEntity
                , cmcSystemDateDataSet.CMCSystemDate[0].SystemDate 
                , orderSystemDate
                , workAutomaticOrderingDataSet
                );
        }
        #endregion

        #region 自動発注データ取得処理 [FsメソッドID: BSFCORR060900002]
        /// <summary>
        /// 自動発注データ取得処理
        /// [FsメソッドID: BSFCORR060900002]
        /// </summary>
        /// <param name="startParameterEntity">>起動パラメータEntity</param>
        /// <param name="cmcSystemDateDataSet">CMC業務日付DataSet</param>
        /// <param name="orderDeliveryDateDecisionCommonInfoEntity">発注日・納品日決定共通情報Entity</param>
        /// <param name="strDistributionPatternDisclosureDataSet">ＳＴＲ物流パターン公開用DataSet</param>
        /// <param name="storeGroupDisclosureDataSet">ＣＭＣ店舗グループ公開DataSet</param>
        /// <param name="strDeliveryPatternDisclosureDataSet">ＳＴＲ便パターン公開用DataSet</param>
        /// <param name="orrOrderTransactionDataSet">ORR発注トランDataSet</param>
        /// <param name="oRRAutomaticOrderingTransactionDataSet">ORR自動発注トランDataSet</param>
        /// <param name="orderTransactionCount">(OUT）発注トラン登録件数</param>
        /// <param name="automaticOrderingTransactionUpdateCount">(OUT)自動発注トラン更新件数</param>
        [FacadeMethod("BSFCORR060900002")]
        public virtual void GetAutoOrderDataLoaderStartProcessing(
              StartParameterEntity startParameterEntity
            , CMCSystemDateDataSet cmcSystemDateDataSet
            , OrderDeliveryDateDecisionCommonInfoEntity orderDeliveryDateDecisionCommonInfoEntity
            , STRDistributionPatternDisclosureDataSet strDistributionPatternDisclosureDataSet
            , StoreGroupDisclosureDataSet storeGroupDisclosureDataSet
            , STRDeliveryPatternDisclosureDataSet strDeliveryPatternDisclosureDataSet
            , ORROrderTransactionDataSet orrOrderTransactionDataSet
            , ORRAutomaticOrderingTransactionDataSet oRRAutomaticOrderingTransactionDataSet
            , ref int orderTransactionCount
            , ref int automaticOrderingTransactionUpdateCount
            )
        {
            //１．伝票種別マスタDataSetを作成する
            BYRSlipTypeMasterDataSet byrSlipTypeMasterDataSet =
                new BYRSlipTypeMasterDataSet();

            // [BSクラスID: BSCORR02001] DIインスタンス化
            IIncrementalUpdateBusiness receptOrder =
                           (IIncrementalUpdateBusiness)ClassObjectUtil.GetBusinessInstance(
                             "BSCORR02001", typeof(IIncrementalUpdateBusiness));

            //２．【発注チェック】(BSCORR02001000003)ビジネスを呼び出す
            //   引数＊法人コード←[起動パラメータEntity．法人コード] 
            //      ＊基準日←[ＣＭＣ業務日付DataSet．ＣＭＣ業務日付テーブル．業務日付] 
            //      ＊発注日・納品日決定共通情報Entity
            //      ＊ORR発注トランDataSet
            //      ＊ＳＴＲ物流パターン公開用DataSet
            //      ＊ＣＭＣ店舗グループ公開DataSet
            //       ・ＳＴＲ便パターン公開用DataSet
            //       ・伝票種別マスタDataSet
            receptOrder.CheckOrder(
                  startParameterEntity.CorporationCode
                , cmcSystemDateDataSet.CMCSystemDate[0].SystemDate
                , orderDeliveryDateDecisionCommonInfoEntity
                , orrOrderTransactionDataSet
                , strDistributionPatternDisclosureDataSet
                , storeGroupDisclosureDataSet
                , strDeliveryPatternDisclosureDataSet
                , byrSlipTypeMasterDataSet
                );


            // [BSクラスID: BSCORR06009] DIインスタンス化
            AutoOrder.Business.IAutoOrderDataLoaderBusiness autoOrder =
                (AutoOrder.Business.IAutoOrderDataLoaderBusiness)ClassObjectUtil.GetBusinessInstance(
                    "BSCORR06009", typeof(AutoOrder.Business.IAutoOrderDataLoaderBusiness)
                );
            
            //３．【自動発注トラン拠出データの発注トラン登録】(BSCORR06009000004)ビジネスを呼び出す
            autoOrder.RegisterOrderingTransactionFromAutomaticOrderingTransaction(
                  orrOrderTransactionDataSet
                , ref orderTransactionCount
                );

            //４．【自動発注トラン更新】(BSCORR06009000005)ビジネスを呼び出す
            autoOrder.UpdateAutomaticOrderingTransaction(
                  oRRAutomaticOrderingTransactionDataSet
                , ref automaticOrderingTransactionUpdateCount
                );
        }
        #endregion

        #region DB更新用DataSetへの自動発注情報取得処理 [FsメソッドID: BSFCORR060900003]
        /// <summary>
        /// DB更新用DataSetへの自動発注情報取得処理
        /// [FsメソッドID: BSFCORR060900003]
        /// </summary>
        /// <param name="automaticOrderDataTakingConditionEntity">（OUT）自動発注データ取込条件Entity</param>
        /// <param name="automaticOrderingTransactionDataRow">自動発注トランDataRow</param>
        /// <param name="orrAutomaticOrderingTransactionDataSet">（OUT）ORR自動発注トランDataSet</param>
        /// <param name="orrOrderTransactionDataSet">（OUT）ORR発注トランDataSet</param>
        /// <param name="orderSystemDate">発注業務実施日時</param>
        [FacadeMethod("BSFCORR060900003")]
        public virtual void GetAutoOrderDataForDataBaseUpdate(
              ref AutomaticOrderDataTakingConditionEntity automaticOrderDataTakingConditionEntity
            , WorkAutomaticOrderingDataSet.ORRAutomaticOrderingTransactionRow automaticOrderingTransactionDataRow
            , ref ORRAutomaticOrderingTransactionDataSet orrAutomaticOrderingTransactionDataSet
            , ref ORROrderTransactionDataSet orrOrderTransactionDataSet
            , DateTime orderSystemDate
            )
        {
            // [BSクラスID: BSCORR06009] DIインスタンス化
            AutoOrder.Business.IAutoOrderDataLoaderBusiness autoOrder =
                (AutoOrder.Business.IAutoOrderDataLoaderBusiness)ClassObjectUtil.GetBusinessInstance(
                    "BSCORR06009", typeof(AutoOrder.Business.IAutoOrderDataLoaderBusiness)
                );
            // １．【DB更新用DataSetへの自動発注情報の取得】（BSCORR06009000003）を呼出す
            autoOrder.GetAutoOrderDataForDataBaseUpdate(
                automaticOrderDataTakingConditionEntity
                , automaticOrderingTransactionDataRow
                , orrAutomaticOrderingTransactionDataSet
                , orrOrderTransactionDataSet
                , orderSystemDate
                );
        }
        #endregion

    }
}

