using System;
using System.Data;
using System.Data.Common;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Data.OleDb;
using System.Data.SqlClient;
using System.Security.Permissions;
using System.Runtime.Serialization;
using NihonUnisys.CoreCenter.Core.User;
using NihonUnisys.CoreCenter.Retail.Common;
using NihonUnisys.CoreCenter.Retail.Ordering.AutoOrder.Business;
using NihonUnisys.CoreCenter.Retail.Ordering.ReceptOrder.Business;

namespace NihonUnisys.CoreCenter.Retail.Ordering.AutoOrder.Business
{
    /// <summary>
    /// PeriodstermSingleItemSalesProcessDataAccessComponent
    /// </summary>
    public class AutoOrderTableAdapter : RetailDataAccessBase
    {
        #region ORR自動発注トラン一覧取得 (DAOCORR06001)
        /// <summary>
        /// ORR自動発注トラン一覧取得 (DAOCORR06001)
        /// </summary>
        /// <param name="startParameterEntity">起動パラメータEntity</param>
        /// <param name="systemDate">業務日付</param>
        /// <param name="systemActDate">発注業務施日時</param>
        /// <param name="workAutomaticOrderingDataSet">SKUコード</param>
        /// <returns>ステータス</returns>
        public int FillByORRAutomaticOrderingTransactionList(
            StartParameterEntity startParameterEntity,
            DateTime systemDate,
            DateTime systemActDate,
            WorkAutomaticOrderingDataSet workAutomaticOrderingDataSet)
        {
            #region 入力チェック。
            if (startParameterEntity == null)
            {
                throw new ArgumentNullException("startParameterEntity");
            }

            if (systemDate == null)
            {
                throw new ArgumentNullException("systemDate");
            }

            if (systemActDate == null)
            {
                throw new ArgumentNullException("systemActDate");
            }
            #endregion

            string sqltext = this.GetByORROrderWorkFillQuery();
            string connectionstring = this.Connection.ConnectionString;
            using (SqlDataAdapter adp = new SqlDataAdapter(sqltext, connectionstring))
            {
                // データベースアクセス処理。
                // 必ず try-finally 句で囲い、コネクションの解放処理を行う。
                try
                {
                    // コネクションオープン
                    adp.SelectCommand.Connection.Open();

                    adp.SelectCommand.Parameters.Add(new SqlParameter("@corporationCode", startParameterEntity.CorporationCode));
                    adp.SelectCommand.Parameters.Add(new SqlParameter("@autoOrderMethodDiv", startParameterEntity.AutoOrderMethodDiv));
                    adp.SelectCommand.Parameters.Add(new SqlParameter("@systemDate", systemDate));

                    // テーブルへ追加
                    adp.Fill(workAutomaticOrderingDataSet.ORRAutomaticOrderingTransaction);
                }
                finally
                {
                    // コネクションクローズ
                    adp.SelectCommand.Connection.Close();
                }
            }

            return 1;
        }
        #endregion

        #region 本部発注取込用ORR発注トラン取得 [DAOCORR06005]

        /// <summary>
        /// DAメソッドID:「DAOCORR06005」
        /// 本部発注取込用ORR発注トランを取得する。
        /// </summary>
        /// <param name="corporationCode">法人コード</param>
        /// <param name="searchQualificationNo">抽出条件番号</param>
        /// <param name="receiveDate">受信日</param>
        /// <param name="receiveNo">受信番号</param>
        /// <param name="receiveBranchNo">受信枝番</param>
        /// <param name="parallelDiv">並列処理区分</param>
        /// <param name="orrOrderTransactionDataSet">ORR発注トランDataSet</param>
        // 2012/02/21 並列処理対応
        public void FillByHeadquartersOrderWork(
            string corporationCode,
            decimal searchQualificationNo,
            DateTime receiveDate,
            int receiveNo,
            int receiveBranchNo,
            string parallelDiv,
            ORROrderTransactionDataSet orrOrderTransactionDataSet)
        {
            using (DbCommand dbCommand = this.Connection.CreateCommand())
            using (SqlDataAdapter adp = new SqlDataAdapter())
            {
                #region SQL文構築

                StringBuilder sqlBuilder = new StringBuilder();
                sqlBuilder.Append("SELECT ");
                sqlBuilder.Append("     ORRHeadquartersOrderHeader.CorporationCode AS [CorporationCode]");
                sqlBuilder.Append("    ,ORRHeadquartersOrderDetail.StoreCd AS [SentStoreCd]");
                sqlBuilder.Append("    ,ORRHeadquartersOrderHeader.UserCd AS [UserCd]");
                sqlBuilder.Append("    ,'30' AS [OrderTypeDiv]");
                sqlBuilder.Append("    ,@ReceiveDate AS [ReceiveDate]");
                // 2012/02/21 並列処理対応
                //sqlBuilder.Append("    ,ROW_NUMBER() OVER(ORDER BY ORRHeadquartersOrderHeader.CorporationCode) AS [ReceiveNo]");
                sqlBuilder.Append("    ,@ReceiveNo + ROW_NUMBER() OVER(ORDER BY ORRHeadquartersOrderHeader.CorporationCode) AS [ReceiveNo]");
                sqlBuilder.Append("    ,@ReceiveBranchNo AS [ReceiveBranchNo]");
                sqlBuilder.Append("    ,ORRHeadquartersOrderDetail.StoreCd AS [OrderStoreCd]");
                sqlBuilder.Append("    ,'' AS [OrderStoreGLNCd]");
                sqlBuilder.Append("    ,ORRHeadquartersOrderHeader.DataTypeDiv AS [OrderFormDiv]");
                sqlBuilder.Append("    ,'' AS [ScanningCdDiv]");
                sqlBuilder.Append("    ,'' AS [ScanningCd]");
                sqlBuilder.Append("    ,ORRHeadquartersOrderHeader.SKUCd AS [SKUCd]");
