            //    ORR自動発注トランDataSet．DataRow.ＳＫＵコード ← 自動発注トランDataRow．ＳＫＵコード
            //    ORR自動発注トランDataSet．DataRow.納品日       ← 自動発注トランDataRow．納品日
            //    ORR自動発注トランDataSet．DataRow.分類１コード ← 自動発注トランDataRow．分類１コード
            orrAutomaticOrderingTransactionDataRow.CorporationCode = automaticOrderingTransactionDataRow.CorporationCode;
