            // 2012/07/24 k.haraikawa start 修正の戻し
            // 2012/06/28 k.haraikawa start
            // ORR自動発注トランDataSetへのデータセット仕様変更
            // ○ORR自動発注トランDataSet．DataRow.予測発注数 ← 自動発注トランDataRow．予測発注数
            // ×ORR自動発注トランDataSet．DataRow.予測発注数 ← 自動発注トランDataRow．予備０７(発注数)
            if (!automaticOrderingTransactionDataRow.IsOrderOfPredictionNull())
            {
                orrAutomaticOrderingTransactionDataRow.OrderOfPrediction = automaticOrderingTransactionDataRow.OrderOfPrediction;
            }
            //if (!automaticOrderingTransactionDataRow.IsAttribute07Null()
            //    && !string.IsNullOrEmpty(automaticOrderingTransactionDataRow.Attribute07))
            //{
            //    orrAutomaticOrderingTransactionDataRow.OrderOfPrediction = Convert.ToInt32(automaticOrderingTransactionDataRow.Attribute07);
            //}
            // 2012/06/28 k.haraikawa end
            // 2012/07/24 k.haraikawa end
            orrAutomaticOrderingTransactionDataRow.TreatmentCompleteDateTime = orderSystemDate;

            //    ORR自動発注トランDataSet．DataRow.予備１ ← 自動発注トランDataRow．予備１
            //    ORR自動発注トランDataSet．DataRow.予備２ ← 自動発注トランDataRow．予備２
            //    ORR自動発注トランDataSet．DataRow.予備３ ← 自動発注トランDataRow．予備３
            //    ORR自動発注トランDataSet．DataRow.予備４ ← 自動発注トランDataRow．予備４
            //    ORR自動発注トランDataSet．DataRow.予備５ ← 自動発注トランDataRow．予備５
            if (!automaticOrderingTransactionDataRow.IsAttribute01Null())
            {
                orrAutomaticOrderingTransactionDataRow.Attribute01 = automaticOrderingTransactionDataRow.Attribute01;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute02Null())
            {
                orrAutomaticOrderingTransactionDataRow.Attribute02 = automaticOrderingTransactionDataRow.Attribute02;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute03Null())
            {
                orrAutomaticOrderingTransactionDataRow.Attribute03 = automaticOrderingTransactionDataRow.Attribute03;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute04Null())
            {
                orrAutomaticOrderingTransactionDataRow.Attribute04 = automaticOrderingTransactionDataRow.Attribute04;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute05Null())
            {
                orrAutomaticOrderingTransactionDataRow.Attribute05 = automaticOrderingTransactionDataRow.Attribute05;
            }

            //    ORR自動発注トランDataSet．DataRow.予備６   ← 自動発注トランDataRow．予備６
            //    ORR自動発注トランDataSet．DataRow.予備７   ← 自動発注トランDataRow．予備７
            //    ORR自動発注トランDataSet．DataRow.予備８   ← 自動発注トランDataRow．予備８
            //    ORR自動発注トランDataSet．DataRow.予備９   ← 自動発注トランDataRow．予備９
            //    ORR自動発注トランDataSet．DataRow.予備１０ ← 自動発注トランDataRow．予備１０            
            if (!automaticOrderingTransactionDataRow.IsAttribute06Null())
            {
            orrAutomaticOrderingTransactionDataRow.Attribute06 = automaticOrderingTransactionDataRow.Attribute06;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute07Null())
            {
                orrAutomaticOrderingTransactionDataRow.Attribute07 = automaticOrderingTransactionDataRow.Attribute07;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute08Null())
            {
            orrAutomaticOrderingTransactionDataRow.Attribute08 = automaticOrderingTransactionDataRow.Attribute08;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute09Null())
            {
            orrAutomaticOrderingTransactionDataRow.Attribute09 = automaticOrderingTransactionDataRow.Attribute09;
            }
            if (!automaticOrderingTransactionDataRow.IsAttribute10Null())
            {
            orrAutomaticOrderingTransactionDataRow.Attribute10 = automaticOrderingTransactionDataRow.Attribute10;
            }

            // 共通項目設定 2011/10/6
            orrAutomaticOrderingTransactionDataRow.LogicalDelDate = automaticOrderingTransactionDataRow.LogicalDelDate;
            orrAutomaticOrderingTransactionDataRow.CreateBy = automaticOrderingTransactionDataRow.CreateBy;
            orrAutomaticOrderingTransactionDataRow.CreateDate = automaticOrderingTransactionDataRow.CreateDate;
            orrAutomaticOrderingTransactionDataRow.UpdateBy = UserProfile.UserId;
            orrAutomaticOrderingTransactionDataRow.UpdateDate = DateTime.Now;
            orrAutomaticOrderingTransactionDataRow.SystemRowversion = automaticOrderingTransactionDataRow.SystemRowversion;

            // 設計書に載っていない必須項目に空文字を追加 2011/09/20
            orrAutomaticOrderingTransactionDataRow.LogicalDelFlg = "0";

            orrAutomaticOrderingTransactionDataSet.ORRAutomaticOrderingTransaction.AddORRAutomaticOrderingTransactionRow(orrAutomaticOrderingTransactionDataRow);

            // 更新内容を確定する
            orrAutomaticOrderingTransactionDataRow.AcceptChanges();

            // RowStateを Modified に変更する
            orrAutomaticOrderingTransactionDataRow.SetModified();

            //３．自動発注データ取込条件Entity．受信番号をカウントアップする
            //  自動発注データ取込条件Entity．受信番号 ←  自動発注データ取込条件Entity．受信番号＋１
            automaticOrderDataTakingConditionEntity.ReceiveNo++;
        }
        #endregion

        #region 自動発注トラン拠出データの発注トラン登録 [BSメソッドID: BSCORR06009000004]
        /// <summary>
        /// 自動発注トラン拠出データの発注トラン登録処理を呼び出す。
        /// </summary>
        /// <param name="orrOrderTransactionDataSet">ORR発注トランDataSet</param>
        /// <param name="orderTransactionCount">発注トラン登録件数</param>
        public virtual void RegisterOrderingTransactionFromAutomaticOrderingTransaction(
              ORROrderTransactionDataSet orrOrderTransactionDataSet
            , ref int orderTransactionCount
            )
        {
            // [BSクラスID: BSCORR02001] DIインスタンス化
            //IReceptOrder receptOrder =
            //    (IReceptOrder)ClassObjectUtil.GetBusinessInstance(
            //    "BSCORR02001", typeof(IReceptOrder));
            IIncrementalUpdateBusiness receptOrder =
                           (IIncrementalUpdateBusiness)ClassObjectUtil.GetBusinessInstance(
                             "BSCORR02001", typeof(IIncrementalUpdateBusiness));

            // 2012/01/23 発注トラン登録効率改善
            //１．【発注トラン登録Bs】(BSCORR02001000034)を呼出す。
            //  引数：＊ＯＲＲ発注トランDataSet
            //  戻り値：処理件数
            //int treatmentNumber = 
            //        receptOrder.RegisterOrderTransaction(
            //            orrOrderTransactionDataSet
            //            );

            // 発注トランへBULK INSERTする。
            int treatmentNumber = receptOrder.BulkInsertORROrderTransaction(orrOrderTransactionDataSet);
            
            // 登録件数を発注トラン登録件数に追加する。
            orderTransactionCount += treatmentNumber;
        }
        #endregion

        #region 自動発注トラン更新 [BSメソッドID: BSCORR06009000005]
        /// <summary>
        /// ＯＲＲ自動発注トラン更新処理を呼び出し、自動発注トラン更新処理を行う。
        /// </summary>
        /// <param name="oRRAutomaticOrderingTransactionDataSet">?ORR自動発注トランDataSet</param>
        /// <param name="automaticOrderingTransactionUpdateCount">(ref)自動発注トラン更新件数</param>
        public virtual void UpdateAutomaticOrderingTransaction(
              ORRAutomaticOrderingTransactionDataSet oRRAutomaticOrderingTransactionDataSet
            , ref int automaticOrderingTransactionUpdateCount
            )
        {
            // ＯＲＲ自動発注トラン更新 [DAメソッドID: DAOCORR06002]を呼び出す
            int updateCount =
                  new ORRAutomaticOrderingTransactionDataSetTableAdapters.ORRAutomaticOrderingTransactionTableAdapter().Update(
                      oRRAutomaticOrderingTransactionDataSet
                    );
            automaticOrderingTransactionUpdateCount += updateCount;
        }
        #endregion
    }
