using NihonUnisys.CoreCenter.Retail.Common.PublicBusiness.Business;
using NihonUnisys.CoreCenter.Retail.Common.Resources;
using NihonUnisys.CoreCenter.Core.User;

namespace NihonUnisys.CoreCenter.Retail.Ordering.AutoOrder.Business
{
    /// <summary>
    /// 自動発注データ取込バッチで使用するクラス。
    /// </summary>
    public class AutoOrderDataLoaderBusiness : BusinessBase, IAutoOrderDataLoaderBusiness
    {
        #region 自動発注データ取込準備をする [BSメソッドID: BSCORR06009000001]
        /// <summary>
        /// （１）（共通公開）ＣＭＣ業務日付取得処理の呼び出し
        /// （２）（商談API)物流区分リスト取得処理の呼び出し
        /// （３）（商談API)便パターンリスト取得処理の呼び出し
        /// （４）自動発注データ取込条件Entityへの値の設定
        /// （５）（基盤API）ＡＰ変数取得（コード指定）処理の呼び出し
        /// （６）（基盤API）ＡＰ変数取得（コード指定）処理の呼び出しを行い、自動発注データ取込準備を行う。
        /// </summary>
        /// <param name="startParameterEntity">起動パラメータEntity</param>
        /// <param name="automaticOrderDataTakingConditionEntity">自動発注データ取込条件Entity</param>
        /// <param name="cmcSystemDateDataSet">CMC業務日付DataSet</param>
        /// <param name="orderDeliveryDateDecisionCommonInfoEntity">発注日・納品日決定共通情報Entity</param>
        /// <param name="strDistributionPatternDisclosureDataSet">ＳＴＲ物流パターン公開用DataSet</param>
        /// <param name="storeGroupDisclosureDataSet">ＣＭＣ店舗グループ公開DataSet</param>
        /// <param name="strDeliveryPatternDisclosureDataSet">ＳＴＲ便パターン公開用DataSet</param>
        /// <param name="apVariablesDataSet">ＡＰ変数DataSet</param>
        public virtual void GetAutoOrderDataLoaderPrepares(
              StartParameterEntity startParameterEntity 
            , AutomaticOrderDataTakingConditionEntity automaticOrderDataTakingConditionEntity 
            , CMCSystemDateDataSet cmcSystemDateDataSet
            , OrderDeliveryDateDecisionCommonInfoEntity orderDeliveryDateDecisionCommonInfoEntity
            , STRDistributionPatternDisclosureDataSet strDistributionPatternDisclosureDataSet
            , StoreGroupDisclosureDataSet storeGroupDisclosureDataSet
            , STRDeliveryPatternDisclosureDataSet strDeliveryPatternDisclosureDataSet
            , APVariablesDataSet apVariablesDataSet
            )
        {
            //１．【ＣＭＣ業務日付取得】（共通公開：BSCCMR01011000008）を呼出す。
            // [BSクラスID: BSCCMR01011000](CMCその他公開API) DIインスタンス化
            ICmcOtherAPI cmcOtherAPI =
                (ICmcOtherAPI)ClassObjectUtil.GetBusinessInstance(
                    "BSCCMR01011000", typeof(ICmcOtherAPI));
            //  （共通API)ＣＭＣ業務日付取得を呼び出す
            // ※INPUTに、以下の情報を設定する。    
            //  ・サブシステムＩＤ = [起動パラメータEntity]．[サブシステムＩＤ]    
            //  ・業務種別         = [起動パラメータEntity]．[業務種別]    
            //  ・法人コード       = [起動パラメータEntity]．[法人コード] 
            cmcOtherAPI.CMCGetSystemDate(
                  startParameterEntity.SubSystemId
                , startParameterEntity.BusinessType
                , startParameterEntity.CorporationCode
                , cmcSystemDateDataSet
               );

            // [BSクラスID: BSCSTR10000](商談API) DIインスタンス化
            ISTRProductControlAPI strProductControlAPI =
                (ISTRProductControlAPI)ClassObjectUtil.GetBusinessInstance(
                    "BSCSTR10000", typeof(ISTRProductControlAPI));
            //２．【（商談API)物流区分リスト取得】（BSCSTR10000000020）ビジネスを呼び出す。
            // ※INPUTに、以下の情報を設定する。
            //  ・法人コード = 法人コード
            strProductControlAPI.GetDistributionPattern(
                  startParameterEntity.CorporationCode
                , ref strDistributionPatternDisclosureDataSet
                , ""
                , ""
                );

            //３．【（商談API)便パターンリスト取得】（BSCSTR10000000019）ビジネスを呼び出す。    
            // ※INPUTに、以下の情報を設定する。    
            //  ・法人コード = 法人コード    
            strProductControlAPI.GetDeliveryPattern(
                  startParameterEntity.CorporationCode
                 ,""
                 , ref strDeliveryPatternDisclosureDataSet
                );

            //４．自動発注データ取込条件Entityに値を設定する。  
            //  ・自動発注データ取込条件Entity．法人コード = [起動パラメータEntity]．[法人コード]  
            //  ・自動発注データ取込条件Entity．発注種別区分＝"10"
            //  ・自動発注データ取込条件Entity．発注形態区分＝"12"
            //  ・自動発注データ取込条件Entity．受信日＝システム日時
            //  ・自動発注データ取込条件Entity．受信番号＝０
            //  ・自動発注データ取込条件Entity．受信枝番＝１
            //  ・自動発注データ取込条件Entity．担当者コード＝[起動パラメータEntity]．[ユーザID]  
            automaticOrderDataTakingConditionEntity.CorporationCode = startParameterEntity.CorporationCode;
            automaticOrderDataTakingConditionEntity.OrderTypeDiv = "10";
            automaticOrderDataTakingConditionEntity.OrderFormDiv = "12";
            // 2012/09/04 k.haraikawa start
            //automaticOrderDataTakingConditionEntity.ReceiveDate = DateTime.Now;
            // ＯＲＲ発注トラン登録時、受信日には現在日時－１００年を設定する。
            automaticOrderDataTakingConditionEntity.ReceiveDate = DateTime.Now.AddYears(-100);
            // 2012/09/04 k.haraikawa end
            automaticOrderDataTakingConditionEntity.ReceiveNo = 0;
            automaticOrderDataTakingConditionEntity.ReceiveBranchNo = 1;
            automaticOrderDataTakingConditionEntity.UserCd = startParameterEntity.UserId;

            //５．【発注日・納品日決定共通情報取得Bs】(BSCORR02001000001)を呼出す
            // [BSクラスID: BSCORR02001] DIインスタンス化
            IIncrementalUpdateBusiness incrementalUpdateBusiness =
                           (IIncrementalUpdateBusiness)ClassObjectUtil.GetBusinessInstance(
                             "BSCORR02001", typeof(IIncrementalUpdateBusiness));

            // 発注日・納品日決定共通情報取得Bs(BSCORR02001000001)を呼出す
            //  [引数設定]
            //  法人コード　←　[起動パラメータEntity]．[法人コード] 
            //  基準日    　←　[ＣＭＣ業務日付DataSet．ＣＭＣ業務日付．業務日付]
            //  発注日・納品日決定共通情報Entity
            //  ＳＴＲ物流パターン公開用DataSet
            //  ＣＭＣ店舗グループ公開DataSet
            incrementalUpdateBusiness.GetOrderDateDeliveryDateDecisionCommonInfo(
                  startParameterEntity.CorporationCode
                , cmcSystemDateDataSet.CMCSystemDate[0].SystemDate
                , orderDeliveryDateDecisionCommonInfoEntity
                , strDistributionPatternDisclosureDataSet
                , storeGroupDisclosureDataSet
                );

            //６．【（基盤API）ＡＰ変数取得（コード指定）】ビジネスを呼び出す。
            //  パラメータは、取得したい各AP変数コードと法人コードを指定し、取得したデータをAP変数DataSetにレコード追加する(APVCORR0032)
            //  ６－１．AP変数「ＯＲＲ発注トランDs設定件数」
            //       AP変数DataSet.DataRowを追加する
            //       引数．AP変数DataSet.DataRow = 戻り値．AP変数取得用DataSet.DataRow
            apVariablesDataSet.UTFAPVariable.AddUTFAPVariableRow(
                  APVariableListKey.ORR_ORDER_TRANSACTION_DATASET_SET_COUNT
                , startParameterEntity.CorporationCode
                , APVariableUtil.GetAPVariableValue(
                      APVariableListKey.ORR_ORDER_TRANSACTION_DATASET_SET_COUNT
                    , startParameterEntity.CorporationCode)
                );

        }
        #endregion

        #region 自動発注トラン取得 [BSメソッドID: BSCORR06009000002]
        /// <summary>
        /// 自動発注トランの取得処理を行う。
        /// ＯＲＲ自動発注トランより、ワーク自動発注情報DataSetに値を設定する。
        /// </summary>
        /// <param name="startParameterEntity">起動パラメータEntity</param>
        /// <param name="systemDate">業務日付</param>
